function [r] = deg2rad(deg)
%DEG2RAD  Degrees to radians, as Octave's deg2rad: deg (pi/180).
%   deg: real[1] (passed a plain number)
%   returns r: real[1] (passed a plain number)
%   Generated by tools/pcode.py from the pseudocode (trinetra-pcode/2); do not edit.
    r = 0;
    r = (deg * (pi / 180));
end
